-- Two Thin Coats: the 42 greys/bones/browns/skin triad paints moved from range 'k' into the triad role ranges
-- O (shadow), N (midtone), H (highlight), per Two Thin Coats' 180-paint chart. Paint keys are "<range>|<code>|<name>",
-- so rewrite every stored key: collections, recipe paint lists and steps, profile favourites and saved wheel selections.

UPDATE OR IGNORE collection SET paint_key = 'O||Doom Death Black' WHERE paint_key = 'k||Doom Death Black';
DELETE FROM collection WHERE paint_key = 'k||Doom Death Black';
UPDATE recipes SET paints = REPLACE(paints, '"k||Doom Death Black"', '"O||Doom Death Black"') WHERE paints LIKE '%k||Doom Death Black%';
UPDATE recipes SET steps = REPLACE(steps, '"k||Doom Death Black"', '"O||Doom Death Black"') WHERE steps LIKE '%k||Doom Death Black%';
UPDATE users SET favourites = REPLACE(favourites, '"k||Doom Death Black"', '"O||Doom Death Black"') WHERE favourites LIKE '%k||Doom Death Black%';
UPDATE users SET wheel = REPLACE(wheel, '"k||Doom Death Black"', '"O||Doom Death Black"') WHERE wheel LIKE '%k||Doom Death Black%';
